SELECT id, change_set_id, status, expires_at, decided_by, decided_at, comment,
       created_at, updated_at, created_by, updated_by
FROM manga_creative_approval WHERE change_set_id = #{changeSetId}

SELECT change_set_id FROM manga_creative_approval
WHERE status = 'PENDING' AND expires_at <= #{now}
ORDER BY expires_at, id LIMIT #{limit}
